-- Athena saved query (Product_B2C_Intl)
-- ID: 2572ec69-5493-483c-a2ba-722be893fb5d
-- Name: Super Optimized Funnel - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH DBS_Routes AS ( SELECT DISTINCT src_id, dest_id FROM "user_interaction"."search_route_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-12 18:30:00' AND campaign_id LIKE '%MULSTL_DBIND%' AND country = 'IND' -- GROUP BY 1, 2 -- Optimized for lookups ), -- Deduped Funnel Steps (1 row per session + route) srp_deduped AS ( SELECT s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, CASE WHEN sr.src_id IS NOT NULL THEN 'DBS Routes' ELSE 'non-DBS Routes' END AS route_type, 1 as srp_hit FROM "user_interaction"."search_route_details" s LEFT JOIN DBS_Routes sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id WHERE s.__time >= TIMESTAMP '2026-01-06 18:30:00' AND s.__time < TIMESTAMP '2026-01-12 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND (s.akamai_bot IS NULL OR s.akamai_bot = '') -- AND s.os = 'Android' AND s.country = 'IND' AND ("position" + "offset" + 1) = 1 GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_deduped AS ( SELECT mri_session_id, route_id, 1 as sl_hit FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-12 18:30:00' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id, 1 as pax_hit FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-12 18:30:00' AND country = 'IND' GROUP BY 1,2 ), tco_deduped AS ( SELECT mri_session_id, route_id, 1 as tco_hit FROM "user_interaction"."create_order_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-12 18:30:00' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, 1 as oi_hit FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-12 18:30:00' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, SUM(tin_count) as total_tins, 1 as conf_hit FROM ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-12 18:30:00' AND country = 'IND' AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) GROUP BY 1,2 ), -- Step 1: Join at Session + Route grain joined_funnel AS ( SELECT srp.mri_session_id, srp.user_type, srp.os, srp.channel, srp.route_type, srp.srp_hit, COALESCE(sl.sl_hit, 0) as sl_hit, COALESCE(pax.pax_hit, 0) as pax_hit, COALESCE(tco.tco_hit, 0) as tco_hit, COALESCE(oi.oi_hit, 0) as oi_hit, COALESCE(conf.conf_hit, 0) as conf_hit, COALESCE(conf.total_tins, 0) as tin_count FROM srp_deduped srp LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id ), -- Step 2: Flatten to Session level to ensure uniqueness session_flattened AS ( SELECT mri_session_id, user_type, os, channel, route_type, MAX(srp_hit) as srp_sess, MAX(sl_hit) as sl_sess, MAX(pax_hit) as pax_sess, MAX(tco_hit) as tco_sess, MAX(oi_hit) as oi_sess, MAX(conf_hit) as conf_sess, SUM(tin_count) as total_tin FROM joined_funnel GROUP BY 1,2,3,4,5 ) SELECT 'Pre Dec 10 to 16' AS month_period, UPPER(user_type) as user_type, -- route_type, -- Toggle this for DBS vs Non-DBS cut 'Overall' AS route_type, 'Overall' AS tuple_type, COALESCE(os, channel) AS saleschannel, SUM(srp_sess) AS srpload, SUM(sl_sess) AS slload, SUM(pax_sess) AS paxload, SUM(tco_sess) AS tcoload, SUM(oi_sess) AS orderinfoload, SUM(conf_sess) AS confirmsession, SUM(total_tin) AS tin FROM session_flattened GROUP BY 1,2,3,4,5;
